args.query:
SELECT spend_row__channel AS channel, SUM(value) AS total
FROM (
  SELECT spend_row__channel, spend_row__spend_date, value
  FROM (
    SELECT spend_row__channel, spend_row__spend_date, value
    FROM (SELECT 'paid_search' AS spend_row__channel, 36875.98 AS value) t
  )
) GROUP BY spend_row__channel;
